  }

  // Aggregate expense accounts
  const accMap = new Map<number, { name: string; jan: number; feb: number }>();
  for (const p of postings) {
    const acc = p.account;
    if (!acc) continue;
    const isExpense = acc.type === "OPERATING_EXPENSES" || (!acc.type && acc.number >= 4000 && acc.number <= 8999);
